class CropRequirements { const CropRequirements({required this.name,required this.minRainfall,required this.maxRainfall,required this.minTemp,required this.maxTemp,required this.minPh,required this.maxPh}); final String name; final double minRainfall,maxRainfall,minTemp,maxTemp,minPh,maxPh; }
class FieldConditions { const FieldConditions({required this.rainfall,required this.temperature,required this.ph}); final double rainfall,temperature,ph; }
class CropSuitabilityResult { const CropSuitabilityResult(this.crop,this.score,this.reasons); final String crop; final int score; final List<String> reasons; }
class CropSuitabilityScorer { const CropSuitabilityScorer(); CropSuitabilityResult score(CropRequirements c,FieldConditions f){final v=[c.minRainfall,c.maxRainfall,c.minTemp,c.maxTemp,c.minPh,c.maxPh,f.rainfall,f.temperature,f.ph];if(v.any((x)=>!x.isFinite)||c.minRainfall>c.maxRainfall||c.minTemp>c.maxTemp||c.minPh>c.maxPh)throw ArgumentError('Invalid ranges');var n=0;final reasons=<String>[];void check(String label,double x,double min,double max,int points){if(x>=min&&x<=max){n+=points;reasons.add('$label in range');}else{reasons.add('$label out of range');}}check('Rainfall',f.rainfall,c.minRainfall,c.maxRainfall,34);check('Temperature',f.temperature,c.minTemp,c.maxTemp,33);check('Soil pH',f.ph,c.minPh,c.maxPh,33);return CropSuitabilityResult(c.name,n,List.unmodifiable(reasons));}}
